        body: `▼ゼロから：配合設計は「料理のレシピづくり」
・コンクリートはセメント・水・細骨材（砂）・粗骨材（砂利）・混和材料の5種類を混ぜたもの
・そのレシピを、1立方メートル（1 m3）あたり何kg入れるかで書いたものが「配合」である
・料理と違うのは、味ではなく「強さ・流れやすさ・長持ちの度合い」を狙って数字を決める点
・配合設計とは、必要な性能を満たす最も経済的な配合を数字で決める作業のこと
・ポイントは順番が決まっていること。強度から水セメント比、流動性から単位水量、と一方通行で進む
⚠ 例えの限界：料理は目分量でも成立するが、コンクリートは1つの数字を変えると強度も耐久性も同時に動く

━━━━━━━━━━━━━━━━━━━━━━
🔑 配合設計で決めるべき数字は7つだけ
━━━━━━━━━━━━━━━━━━━━━━
・粗骨材の最大寸法（Gmax）：部材寸法・鉄筋のあきから決める
・スランプ（またはスランプフロー）：施工方法から決める
・空気量：耐凍害性とワーカビリティーから決める
・水セメント比（W/C）：強度・耐久性・水密性のうち最も厳しい条件から決める★
・単位水量（W）：所要のスランプが得られる範囲でできるだけ小さく★
・細骨材率（s/a）：材料分離せずワーカビリティーが良い最小値
・単位量（W・C・S・G・混和剤量）：絶対容積法で計算する
→ この7つが決まれば配合表は完成する。逆にどれか1つ欠けても計算できない

━━━━━━━━━━━━━━━━━━━━━━
🔑 手順の流れ：上から順に一方通行
━━━━━━━━━━━━━━━━━━━━━━
・第1段階：設計図書から設計基準強度・耐久性・環境条件を読み取る
・第2段階：品質基準強度を決め、変動を見込んで配合強度を求める★
・第3段階：配合強度から水セメント比を求める（強度式・実験式）
・第4段階：耐久性・水密性からの水セメント比の上限と比べ、小さいほうを採用★
・第5段階：スランプ・空気量・粗骨材最大寸法を決め、単位水量を仮定する
・第6段階：単位セメント量＝単位水量÷水セメント比で計算する
・第7段階：細骨材率を仮定し、絶対容積法で単位細骨材量・単位粗骨材量を求める
・第8段階：試し練りを行い、スランプ・空気量を実測して配合を修正する★
・第9段階：示方配合を現場配合に換算して発注・製造する
⚠ 第4段階を飛ばすのが最頻出のミス。強度だけで決めた水セメント比は耐久性を満たさないことがある

【図解】配合設計の各段階と決定根拠
　段階｜決める量｜主な根拠
　1｜品質基準強度｜設計基準強度と耐久性基準強度の大きいほう★
　2｜配合強度｜品質基準強度＋変動のばらつき分
　3｜水セメント比｜強度式と耐久性上限の小さいほう★
　4｜単位水量｜スランプ・Gmax・骨材の形状
　5｜細骨材率｜分離しない最小値
　6｜各単位量｜絶対容積法の計算
　⚠ 表の上から順に決まる。下の段階から上へ戻る矢印は原則ない

━━━━━━━━━━━━━━━━━━━━━━
🔑 「できるだけ小さく」が3つある
━━━━━━━━━━━━━━━━━━━━━━
・単位水量：小さいほど乾燥収縮・ブリーディングが減る★
・単位セメント量：小さいほど水和熱・自己収縮・コストが減る
・細骨材率：小さいほど同じスランプに必要な単位水量が減る★
→ ただしいずれも小さすぎるとワーカビリティーが失われ、施工できなくなる
→ 「所要の品質が得られる範囲でできるだけ小さく」が示方書の決まり文句
・逆に「できるだけ大きく」するのは粗骨材の最大寸法（許される範囲で大きく）

━━━━━━━━━━━━━━━━━━━━━━
🔑 示方配合と現場配合の違い
━━━━━━━━━━━━━━━━━━━━━━
・示方配合：骨材が表面乾燥飽水状態（表乾）で、細骨材は5mmふるいを全通、粗骨材は全部5mmに留まると仮定した理想の配合★
・現場配合：実際の骨材の表面水率と粒度を反映して、計量器で量る数字に直したもの★
・両者は同じコンクリートを指す。書き換えただけで品質は変わらない
・現場配合の計算には（1）粒度の補正（2）表面水量の補正の2段階が必要
⚠ ひっかけ：×示方配合は設計者が決め、現場配合は品質が違う → ○同一のコンクリートの表現違い

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「配合設計において最初に決めるのはどれか」→ 粗骨材最大寸法・スランプなど施工条件が先
・「水セメント比の決定に用いないものはどれか」→ 細骨材率は水セメント比の決定に無関係★
・「単位水量を小さくする効果として誤りはどれか」→ ×強度が下がる（同じW/Cなら強度はほぼ不変）
・「示方配合から現場配合への換算で変わらないものは」→ 単位セメント量★
・記述式では「単位水量を小さくすべき理由を3つ挙げよ」が定番

★ここだけ暗記
・順番は 品質基準強度 → 配合強度 → 水セメント比 → 単位水量 → 単位セメント量 → 細骨材率 → 絶対容積法
・水セメント比は「強度から求めた値」と「耐久性・水密性の上限」の小さいほうを採る
・小さくするのは W・C・s/a、大きくするのは Gmax
・示方配合と現場配合は同じコンクリートの別表現で、単位セメント量は不変`,
