        body: `▼ゼロから：なぜ強度を3段階も使い分けるのか
・橋や建物を設計する人は「このコンクリートは30 N/mm2ある前提で計算しました」と決める。これが設計基準強度
・ところが実際に作ったコンクリートは、同じ配合でも1本ごとに強度がばらつく
・28 N/mm2の日もあれば33 N/mm2の日もある。平均を30ちょうどにすると、半分は30を下回ってしまう
・だから工場は「平均で35くらい出る配合」にしておく。この狙いの平均値が配合強度★
・さらに「凍害に耐えるには最低でも30必要」といった耐久性の要求も加わる。これを含めた合格ラインが品質基準強度
⚠ 例えの限界：ばらつきは不良ではなく材料と作業に必然的に伴うもの。ゼロにはできない

━━━━━━━━━━━━━━━━━━━━━━
🔑 3つの強度の定義を正確に
━━━━━━━━━━━━━━━━━━━━━━
・設計基準強度（f'ck）：構造計算で用いる圧縮強度。設計者が決める★
・耐久性基準強度（f'cd）：想定される劣化作用に耐えるために必要な圧縮強度
・品質基準強度（f'cq）：設計基準強度と耐久性基準強度のうち大きいほう★
・配合強度（f'cr）：品質基準強度を下回る確率が小さくなるよう割増した、配合を決めるための強度★
→ 大小関係は必ず 配合強度 ＞ 品質基準強度 ≧ 設計基準強度 となる
⚠ ひっかけ：×配合強度は設計基準強度と等しい → ○必ず配合強度のほうが大きい

━━━━━━━━━━━━━━━━━━━━━━
🔑 配合強度を求める2つの式（両方を満たす）
━━━━━━━━━━━━━━━━━━━━━━
・式1：f'cr ≧ f'cq ＋ 1.73σ（不良率5%以下を保証する条件）★
・式2：f'cr ≧ 0.85 f'cq ＋ 3σ（1回の試験値が品質基準強度の85%を下回る確率を小さくする条件）★
・σ は圧縮強度の標準偏差（N/mm2）。実績がなければ想定値を使う
・両方を計算し、大きいほうを配合強度とする★
・1.73 は正規分布で上側5%点にあたる係数（標準正規分布の1.645を3個平均で読み替えたもの）
→ σが小さい優秀な工場ほど、配合強度を低く設定でき経済的になる

【図解】配合強度の計算例（品質基準強度30 N/mm2、標準偏差3.0 N/mm2）
　式｜計算｜結果
　式1｜30＋1.73×3.0｜35.2 N/mm2★
　式2｜0.85×30＋3×3.0｜34.5 N/mm2
　採用値｜大きいほう｜35.2 N/mm2★
　⚠ 小さいほうを採る誤りが最頻出。安全側は必ず大きいほう

【図解】標準偏差が変わると配合強度はどう動くか（品質基準強度30 N/mm2）
　標準偏差σ｜式1の値｜式2の値｜採用値
　2.0｜33.5｜31.5｜33.5
　3.0｜35.2｜34.5｜35.2
　4.5｜37.8｜39.0｜39.0★
　6.0｜40.4｜43.5｜43.5★
　⚠ σが大きいと式2のほうが支配的になる。必ず両式を計算すること

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築（JASS 5）での呼び名との対応
━━━━━━━━━━━━━━━━━━━━━━
・設計基準強度 Fc、耐久設計基準強度 Fd、品質基準強度 Fq＝max(Fc, Fd)
・調合管理強度 Fm＝Fq＋構造体強度補正値 mSn★
・調合強度 F ≧ Fm＋1.73σ かつ F ≧ 0.85Fm＋3σ
・構造体強度補正値は、標準養生供試体と構造体コンクリートの強度差を埋める上乗せ分（通常3または6 N/mm2）
→ 土木の「配合強度」と建築の「調合強度」はほぼ同じ考え方だが、構造体強度補正値が入る点が建築の特徴★

━━━━━━━━━━━━━━━━━━━━━━
🔑 レディーミクストコンクリートの呼び強度
━━━━━━━━━━━━━━━━━━━━━━
・呼び強度：JIS A 5308で購入者が指定する強度の呼び。単位はつけずに数字だけで表す
・強度の合格判定は2つ：1回の試験値が呼び強度の85%以上、かつ3回の試験値の平均が呼び強度以上★
・1回の試験値＝任意の1運搬車から採った3個の供試体の平均値★
・つまり「1個の値」ではなく「3個の平均」が1回の試験値である点に注意
⚠ ひっかけ：×供試体1個が呼び強度の85%を下回ったら不合格 → ○3個平均で判定する

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「品質基準強度の定義として正しいものは」→ 設計基準強度と耐久性基準強度の大きいほう
・数値問題：f'cq と σ を与えて配合強度を計算させる。2式の大きいほうを選ばせる出題が定番★
・「標準偏差が大きい工場ほど配合強度は」→ 大きくなる（不経済）
・「呼び強度27で1回の試験値が23.5 N/mm2だった。合否は」→ 27×0.85＝22.95 なので単独では合格

★ここだけ暗記
・大小関係は 配合強度 ＞ 品質基準強度 ≧ 設計基準強度
・品質基準強度＝設計基準強度と耐久性基準強度の大きいほう
・配合強度は f'cq＋1.73σ と 0.85f'cq＋3σ の大きいほう
・レディーミクストの判定は「1回85%以上」かつ「3回平均が呼び強度以上」`,
