・その水はやがて蒸発し、あとに小さな穴（毛細管空隙）が残る★
・穴だらけの接着剤は当然弱い。だから水が多いほど強度は下がる
・水とセメントの比率を表すのが水セメント比W/C。コンクリートの性質を左右する最重要の数字★
