・支えを失ったコンクリートは自分の重さで沈む。この沈んだ量［cm］がスランプ★
・沈みが大きい＝やわらかい＝流れやすい。沈みが小さい＝硬い＝形を保つ
・8cmなら標準的、18cmならかなりやわらかい、0cmは超硬練りでダムなどに使う
