・示方配合は「砂は完全に5mm以下、砂利は完全に5mm以上、どちらも表面が乾いていて内部は水で満たされた状態」という理想を前提にしている★
・ところが現場の砂には5mmより大きい粒が混じり、砂利には5mmより小さい粒が混じっている
・さらに屋外に山積みされた砂は雨に濡れて表面に水がついている（表面水）
・この表面水は練混ぜ水の一部になるので、そのぶん水の計量値を減らさなければならない★
・示方配合を実際の計量値に直す作業が現場配合への換算である
