        body: `▼ゼロから：似た言葉が4つある
・まだ固まっていないコンクリートの「扱いやすさ」を表す言葉が複数ある
・ワーカビリティーは全体としての作業のしやすさ。一番広い概念★
・コンシステンシーは「やわらかさ・変形のしにくさ」だけを指す。スランプで測れる部分★
・プラスティシティーは「まとまりのよさ・分離しにくさ」。粘り気に近い
・フィニッシャビリティーは「仕上げのしやすさ」。表面をコテで押さえやすいかどうか
⚠ 例えの限界：どれも数値で直接測れる量ではない。測れるのはコンシステンシーだけ

━━━━━━━━━━━━━━━━━━━━━━
🔑 4つの用語の定義
━━━━━━━━━━━━━━━━━━━━━━
・ワーカビリティー（施工軟度）：運搬・打込み・締固め・仕上げなど一連の作業のしやすさ、
　および材料分離に対する抵抗性の程度を表す総合的な性質★
・コンシステンシー（稠度）：主として水量の多少による変形あるいは流動に対する抵抗性の程度★
・プラスティシティー（可塑性）：容易に型枠に詰められ、型枠を外すとゆっくり形を変えるが
　崩れたり材料が分離したりしない性質★
・フィニッシャビリティー（仕上げ性）：粗骨材の最大寸法・細骨材率・骨材の粒度・
　コンシステンシーなどによる仕上げのしやすさの程度★
→ 包含関係：ワーカビリティー ⊃ コンシステンシー、プラスティシティー、フィニッシャビリティー

【図解】4つの用語の要点比較
　用語｜意味の中心｜測れるか
　ワーカビリティー｜作業全体のしやすさ★｜直接は測れない
　コンシステンシー｜やわらかさ・流動抵抗｜スランプ試験で測る★
　プラスティシティー｜まとまり・分離抵抗｜直接は測れない
　フィニッシャビリティー｜仕上げのしやすさ｜直接は測れない
　⚠ 「ワーカビリティーはスランプで測る」は誤り。スランプが測るのはコンシステンシー★

━━━━━━━━━━━━━━━━━━━━━━
🔑 その他の関連用語
━━━━━━━━━━━━━━━━━━━━━━
・ポンパビリティー：ポンプ圧送のしやすさ★
・材料分離抵抗性：粗骨材とモルタルが分かれにくい性質
・自己充填性：締固めなしで隅々まで充填される性質（高流動コンクリート）★
・ブリーディング：練混ぜ水の一部が表面に上昇する現象
・レイタンス：ブリーディングに伴って表面に浮き出る微細な物質の層★
・こわばり（スティフニング）：時間とともにコンシステンシーが失われる現象

━━━━━━━━━━━━━━━━━━━━━━
🔑 ワーカビリティーに影響する要因
━━━━━━━━━━━━━━━━━━━━━━
・単位水量：多いほどやわらかいが分離しやすい★
・単位セメント量：少なすぎるとペースト不足でざらつく
・細骨材率：小さすぎると分離、大きすぎると水を食う★
・骨材の粒形・粒度：丸く粒度分布のよい骨材ほど良好
・空気量：適量の連行空気はワーカビリティーを大幅に改善する★
・混和剤：AE減水剤・高性能AE減水剤は水を減らしつつ流動性を保つ
・温度：高温ほどこわばりが早く、ワーカビリティーは失われやすい★
・練混ぜ時間：不足するとむらが残り、過度だと空気が抜ける

━━━━━━━━━━━━━━━━━━━━━━
🔑 コンシステンシーの測定方法
━━━━━━━━━━━━━━━━━━━━━━
・スランプ試験（JIS A 1101）：最も一般的。軟練りから中程度に適する★
・スランプフロー試験（JIS A 1150）：軟らかい高流動・高強度コンクリート用★
・振動台式コンシステンシー試験（VC試験、JIS A 1138）：超硬練りコンクリート用★
・貫入試験（プロクター貫入抵抗）：凝結の判定に使う
・落下高さ・沈下度試験：舗装や工場製品で使う
⚠ 超硬練り（スランプ0cm付近）はスランプ試験では差が出ない。VC試験を使う★

【図解】コンシステンシーの試験方法の使い分け
　試験｜適用範囲｜測る量
　スランプ試験｜スランプ2.5〜21cm★｜沈下量［cm］
　スランプフロー試験｜高流動・高強度★｜広がり直径［cm］
　VC試験｜超硬練り（ダム・舗装）★｜振動時間［秒］
　⚠ ダムのRCD工法ではVC値（秒）で管理する

━━━━━━━━━━━━━━━━━━━━━━
🔑 本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「ワーカビリティーの定義として正しいものは」→ 作業のしやすさと材料分離抵抗性の総合★
・「コンシステンシーの定義」→ 主として水量の多少による変形・流動に対する抵抗性
・「スランプ試験で測定されるのは」→ コンシステンシー★
・「フィニッシャビリティーに影響しないものは」→ セメントの種類より粗骨材の最大寸法が主
・用語の入れ替え問題が定番。定義文をそのまま覚えるのが早い

★ここだけ暗記
・ワーカビリティーは総合概念、スランプが測るのはコンシステンシー
・プラスティシティーは分離せずゆっくり変形する性質
・フィニッシャビリティーは仕上げのしやすさ
・超硬練りはVC試験、高流動はスランプフロー試験`,
