・放っておけば粗骨材は沈み、水は浮き上がろうとする★
・この「材料の分布が均一でなくなる現象」を材料分離という
・分離するとある場所は砂利ばかり、ある場所はモルタルばかりになる
・砂利ばかりの部分は空隙だらけになり、これがジャンカ（豆板）である★
