━━━━━━━━━━━━━━━━━━━━━━
・一般の構造物：材齢28日を基準とする★
・ダム・マスコンクリート：材齢91日を基準にすることが多い★
・高炉セメント・フライアッシュを多量に使う場合：材齢56日または91日★
・道路橋の床版・プレキャスト製品：早期の脱型が必要なので3日・7日を管理材齢とする
