・「以下」「以上」の向きを入れ替えた誤り選択肢が定番★
・単位の入れ替え（kg/m3と%、cm3/cm2とcm3）にも注意★
・計算問題は絶対容積法と配合強度が最頻出★
・記述式では「単位水量を小さくすべき理由」「材料分離の防止対策」が定番

